<script lang="ts">
  import { client } from '$lib/api/client.svelte'
  import type {
    ApproveRegistrationApplication,
    RegistrationApplicationView,
  } from '$lib/api/types'
  import { profile } from '$lib/app/auth'
  import { errorMessage } from '$lib/app/error'

  import ApplicationDenyModal from '$lib/feature/moderation/ApplicationDenyModal.svelte'
  import UserLink from '$lib/feature/user/UserLink.svelte'
  import { publishedToDate } from '$lib/ui/util/date'
  import { Button, ButtonGroup, Label, Material, toast } from 'mono-svelte'
  import RelativeDate from 'mono-svelte/util/RelativeDate.svelte'
  import {
    Check,
    Icon,
    ShieldCheck,
    ShieldExclamation,
    XMark,
  } from 'svelte-hero-icons/dist'

  interface Props {
    application: RegistrationApplicationView
  }

  let { application = $bindable() }: Props = $props()

  let approving = $state(false)
  let denying = $state(false)
  let denyReason = $state('')
  let reviewing = $state(false)

  async function review(approve: boolean) {
    if (!profile.current?.jwt) return

    let registrationApplicationAnswer: ApproveRegistrationApplication = {
      approve: approve,
      id: application.registration_application.id,
    }

    if (approve) {
      approving = true
    } else {
      reviewing = true
      while (reviewing) {
        await new Promise((res) => setTimeout(res, 1000))
      }
      if (!denying) {
        denyReason = ''
        return
      }
      if (denyReason != '') {
        registrationApplicationAnswer.deny_reason = denyReason
      }
    }

    try {
      await client().approveRegistrationApplication(
        registrationApplicationAnswer,
      )
      toast({
        content: approve
          ?'Approved that application.'
          :'Denied that application.',
        type: 'success',
      })
      application.creator_local_user.accepted_application = approve
      application.admin = profile.current.user!.local_user_view.person
      application.registration_application.deny_reason = denyReason

      profile.inbox.notifications.applications -= 1
    } catch (err) {
      toast({
        content: errorMessage(err as string),
        type: 'error',
      })
    }

    approving = false
    denying = false
    denyReason = ''
  }
</script>

{#if reviewing}
  <ApplicationDenyModal
    bind:open={reviewing}
    bind:denying
    bind:denyReason
    user={application.creator}
  />
{/if}
<div class="flex flex-col gap-2">
  <div class="flex flex-col gap-2">
    <span class="text-slate-600 dark:text-zinc-400 text-xs">
      <RelativeDate
        date={publishedToDate(application.registration_application.published)}
      />
    </span>

    <span class="text-sm">
      <UserLink user={application.creator} avatar avatarSize={20} />
    </span>
  </div>
  <div>
    <Material
      color="uniform"
      rounding="xl"
      padding="none"
      class="dark:bg-zinc-925 p-3 py-2"
    >
      <p>{application.registration_application.answer}</p>
    </Material>
  </div>
  <div class="flex flex-row gap-1">
    <div class="flex flex-col md:flex-row gap-2 md:items-center">
      {#if application.admin}
        {@const accepted = application.creator_local_user.accepted_application}
        {#if typeof application.registration_application.deny_reason !== 'undefined' && application.registration_application.deny_reason !== ''}
          <div>
            <div class="flex items-center gap-1 text-sm">
              <Icon
                src={accepted ? ShieldCheck : ShieldExclamation}
                mini
                size="20"
                class={accepted ? 'text-green-400' : 'text-red-400'}
              />
              <UserLink avatar user={application.admin} />
              <Label>
                {accepted
                  ?'Approved'
                  :'Denied'}
              </Label>
              <Label>:</Label>
            </div>
            <p>{application.registration_application.deny_reason}</p>
          </div>
          <div class="md:ml-auto"></div>
        {:else}
          <div class="flex items-center gap-1 text-sm">
            <Icon
              src={accepted ? ShieldCheck : ShieldExclamation}
              mini
              size="20"
              class={accepted ? 'text-green-400' : 'text-red-400'}
            />
            <UserLink avatar user={application.admin} />
            <Label>
              {accepted
                ?'Approved'
                :'Denied'}
            </Label>
          </div>
          <div class="md:ml-auto"></div>
        {/if}
      {/if}
    </div>
    <div class="flex-1"></div>
    <ButtonGroup orientation="horizontal" class="flex">
      <Button
        size="square-md"
        class="hover:bg-slate-200 {application.creator_local_user
          .accepted_application === false && application.admin
          ? 'text-red-500!'
          : ''}"
        aria-label=Deny
        onclick={() => review(false)}
        loading={denying || reviewing}
        disabled={approving || denying || reviewing}
        icon={XMark}
      ></Button>
      <Button
        size="square-md"
        class="hover:bg-slate-200 {application.creator_local_user
          .accepted_application
          ? 'text-green-500!'
          : ''}"
        title=Approve
        onclick={() => review(true)}
        loading={approving}
        disabled={approving || denying || reviewing}
        icon={Check}
      ></Button>
    </ButtonGroup>
  </div>
</div>
